import itertools

def solve_small(n):
    perms = list(itertools.permutations(range(n)))
    total_sum = 0
    for p in perms:
        # sign
        inversions = 0
        for i in range(n):
            for j in range(i + 1, n):
                if p[i] > p[j]:
                    inversions += 1
        sigma = 1 if inversions % 2 == 0 else -1

        # fixed points
        v = 0
        for i in range(n):
            if p[i] == i:
                v += 1

        total_sum += sigma / (v + 1)
    return total_sum

for n in range(1, 6):
    print(f"n={n}: {solve_small(n)}")

