import numpy as np

def get_Tk_list(n):
    perms = list(itertools.permutations(range(n)))
    T = [0] * (n + 1)
    for p in perms:
        v = 0
        for i in range(n):
            if p[i] == i:
                v += 1
        inversions = 0
        for i in range(n):
            for j in range(i + 1, n):
                if p[i] > p[j]:
                    inversions += 1
        sigma = 1 if inversions % 2 == 0 else -1
        for k in range(n + 1):
            T[k] += sigma * (v**k)
    return T

def get_P_coeffs(n):
    # P(j) = 1/(j+1) for j=0..n
    # P(x) = sum_{j=0}^n (1/(j+1)) * product_{i != j} (x-i)/(j-i)
    coeffs = np.zeros(n + 1)
    for j in range(n + 1):
        # Compute L_j(x) = product_{i != j} (x-i)/(j-i)
        # The coefficients of L_j(x) can be found by multiplying (x-i)/(j-i)
        poly = np.poly1d([1])
        denom = 1
        for i in range(n + 1):
            if i == j:
                continue
            poly *= np.poly1d([1, -i])
            denom *= (j - i)
        coeffs += (1 / (j + 1)) * (poly / denom)
    return coeffs

