for n in range(1, 6):
    T = get_Tk_list(n)
    coeffs = get_P_coeffs(n)
    # The sum is sum_{k=0}^n coeffs[n-k] * T[k]
    # Wait, np.poly1d's coeffs are in decreasing order: coeffs[0] is x^n, coeffs[n] is x^0
    # So the sum is sum_{k=0}^n coeffs[n-k] * T[k]
    res = sum(coeffs[n-k] * T[k] for k in range(n + 1))
    print(f"n={n}: sum={res}")

