def solve_small_n(n):
    import itertools

    def sign(p):
        s = 1
        i = 0
        visited = [False] * len(p)
        while i < len(p):
            if not visited[i]:
                j = i
                count = 0
                while not visited[j]:
                    visited[j] = True
                    j = p[j]
                    count += 1
                if count % 2 == 0:
                    s *= -1
            i += 1
        return s

    def fixed_points(p):
        return sum(1 for i, val in enumerate(p) if i == val)

    total_sum = 0
    for p in itertools.permutations(range(n)):
        total_sum += sign(p) / (fixed_points(p) + 1)
    return total_sum

for n in range(1, 7):
    print(f"n={n}, sum={solve_small_n(n)}")
